{
  "evidence": [
    {
      "id": 1,
      "fact": "In Diedrich v. Berryhill, 874 F.3d 634 (9th Cir. 2017), the Ninth Circuit held that an Administrative Law Judge (ALJ) errs by ignoring competent evidence that contradicts the ALJ's findings, specifically regarding the failure to call a medical advisor when there were large gaps in medical records and the need to determine a precise disability onset date.",
