{
  "evidence": [
    {
      "id": 1,
      "fact": "Robert MacLean was fired by the TSA on April 11, 2006, for disclosing a proposed plan to remove air marshals from long-distance flights to MSNBC.",
      "source_date": "2006-04-11"
    },
    {
